def add(ch,title,kind='columns',claim='',left=None,right=None,rows=None,headers=None,notes='',sources=None,**kwargs):
 s=dict(chapter=ch,title=title,kind=kind,claim=claim,notes=notes,sources=sources or [ARCH])
 for k,v in dict(left=left,right=right,rows=rows,headers=headers,**kwargs).items():
  if v is not None:s[k]=v
 slides.append(s)
def pair(label,body):return dict(label=label,body=body)

add('系统设计说明','人生管理系统 4.0','cover',claim='整体协调 · 科学决策 · 主动服务',subtitle='总控架构、9个人生领域、23个共享能力模块与运行机制',notes='本演示面向希望理解、讨论和落地该系统的用户、产品与技术合作者。4.0是人生整体管理架构，3.0是保留在内部的单次决策引擎版本。当前成果是Skill、协议、模板和核算工具；尚不能据此宣称持续采集、后台调度与商业软件已部署。')
add('阅读地图','先看整体，再理解每一层','table',claim='从设计理由走到真实运行，最后用完整案例检验逻辑。',headers=['部分','要回答的问题'],rows=[['设计基础','为什么需要整体协调？借鉴哪些系统思想？'],['总控与领域','谁决定目标？9个领域怎样分工与共同用资源？'],['决策与知识','8个阶段如何推进？23个模块分别交付什么？'],['协作与主动服务','怎样派工、复核、获取资料、补问和通知？'],['实现与验证','怎样形成可运行产品？怎样知道它真正有用？']],notes='可以顺序阅读，也可以凭页脚章节定位。每个领域和每个能力模块都单独展开，讲者备注补充输入、方法与边界。本演示中的资源数字均为明确标注的合成例子，不代表用户的实际预算、行为或能力。')
add('01 设计基础','每个决定都在占用共同资源',claim='单项看起来合理，组合起来可能无法执行。',left=[pair('常见局部计划','职业想增加项目；学习想加课；家庭已有承诺。'),pair('共同限制','这些计划竞争同一份时间、资金和可承受负荷。')],right=[pair('总控的任务','把计划放在一起检查，找出真实冲突与可调整之处。'),pair('需要保留的价值','休息、关系和自由时间可以本身值得保留。')],notes='这是一条设计出发点，而非关于所有人的统计结论。系统把用户当前目标和承诺纳入共同视野，避免每个建议孤立地增加任务。总控既可建议新增行动，也可建议缩减、延期或暂不调整。')
add('01 设计基础','目标是让选择有依据、能落实','three',claim='系统围绕三个连续的问题提供帮助。',items=[pair('看清现状','知道哪些已证实，哪些尚未知；发现目标与资源冲突。'),pair('形成选择','生成真实备选，比较代价、风险、可逆性与反转条件。'),pair('推动修正','在授权内行动，观察结果，再更新方案和相关判断。')],notes='“有依据”不等于绝对正确，“能落实”不等于已经执行，“有反馈”不等于改善一定由系统引起。这三项分别需要证据记录、行动记录和结果观察支持。系统维护的是可以检查和修正的工作方式。')
add('01 设计基础','三类理论提供不同的启发','table',claim='原理论、现代控制知识与本项目设计需要分开表述。',headers=['来源方向','借鉴什么','本系统中的应用'],rows=[['工程控制与现代控制','状态、观测、干预与反馈','看清测量误差、效果延迟和调整幅度'],['系统工程','整体目标、资源、接口与验证','检查各领域组合是否满足共同约束'],['综合集成方法','结合具体资料、人的判断和计算','用证据与实际结果持续修正认识']],notes='钱学森相关原文为《再谈开放的复杂巨系统》高校转载。现代状态空间、可观测性等概念参考MIT课程资料，不能全归于某一篇钱学森文章。九领域分类、八阶段流程和总控运行规则是本项目的应用设计；不宣称该理论证明了人生可控或最优。1954年《工程控制论》未在本轮通读。',sources=[Q,N,MIT])
add('01 设计基础','整体设计必须管理接口','columns',claim='领域之间的影响，需要有责任、条件和反馈记录。',left=[pair('分工','每个领域维护一类生活结果，每件行动只有一个主责。'),pair('接口','记录它影响谁、需要什么资源、何时产生效果。')],right=[pair('整体检查','局部收益不能自动抵消另一领域的底线损害。'),pair('验证目的','同时问“任务是否完成”和“是否帮助了原目标”。')],notes='系统工程对整体性、接口及验证/确认的区分提供了参考。这里把它们转成人生管理中的责任与影响记录。这种迁移是设计判断，不是NASA对产品效果的认可；也无需照搬大型工程的完整审批流程。',sources=[N,I,ARCH])
add('01 设计基础','观测指标只是状态的线索','table',claim='系统必须保存“看到了什么”与“由此推断什么”的区别。',headers=['真实关切','可观察线索','需要防止的误判'],rows=[['学习能力','练习、作品、独立完成情况','学习时长增加就等于能力增长'],['工作进展','交付物、验收、实际完成记录','日历上有计划就等于任务完成'],['关系体验','自愿沟通、履约情况、本人感受','消息数量代表关系质量'],['负荷与恢复','本人描述、作息和相关记录','单一数字代表全部状态']],notes='表内是本系统用于说明观察边界的例子，不是诊断工具。观测指标有覆盖范围、更新时间和误差；没有记录时应保留未知。控制理论中的可观测性有明确模型条件，我们没有为真实人生建立满足这些条件的数学模型。',sources=[ARCH,MIT])
add('01 设计基础','反馈需要等待结果显现','three',claim='记录可以频繁，策略调整要考虑反馈延迟。',items=[pair('先写预期','行动希望改变什么？何时可能看到结果？用什么观察？'),pair('区分原因','偏差可能来自测量、执行、机制假设或外部环境。'),pair('适度调整','先检查条件再改动；尚未成熟的结果不直接算失败。')],notes='反馈并不自动带来稳定。现代控制理论讨论稳定性时需要模型和适用条件；本系统只借鉴关注延迟与调整力度的原则。实际等待时长、停止条件和调整上限应由具体任务的证据与用户条件决定，不设万能数值。',sources=[MIT,ARCH])
add('02 总控架构','一套架构承载四种不同职责','diagram',claim='用户定方向，总控做协调，领域维护结果，能力模块承担具体方法。',diagram='architecture',notes='图中的箭头表示输入、派工和反馈关系，不能理解为AI控制人的意愿。复核与记录横贯全流程。领域与能力模块按需启动，不是要求同时运行32个常驻代理。',sources=[ARCH,ENGINE])
add('02 总控架构','领域、能力、阶段不能混为一谈','table',claim='三个编号体系分别回答：管什么、用什么、做到哪一步。',headers=['对象','数量与编号','职责与交付'],rows=[['人生领域','9个：D01—D09','维护健康、关系、职业等生活结果'],['共享能力','23个：M01—M23','用知识、方法和工具产出分析'],['决策阶段','8个：S1—S8','规定当前必须完成的产物与检查'],['总控','主协调者承担8项职能','协调目标、版本、资源、执行与反馈'],['复核角色','R01','检查证据、反例、遗漏与跨域后果']],notes='一个领域会调用多个能力，一个能力也会在多个领域和阶段使用。例如学习领域D05可以在S2调用检索，在S4调用运筹，在S8调用因果分析。总控的8项职能不是新增8个AI角色。')
add('02 总控架构','用户价值位于总控之上',left=[pair('方向与目标','当前希望改善什么，期限是什么，哪些成果有意义。'),pair('底线与承诺','不能牺牲的条件、已答应的事情和允许探索的范围。')],right=[pair('保留真实取舍','收入、关系、体验等目标不自动折成单一总分。'),pair('目标变更','系统可以提出反思；改变方向仍以用户实际选择为准。')],notes='目标、愿望、承诺和允许动作应分别记录。用户选择收入更重要或自由时间更重要，是价值取舍，不由统计模型直接推导。其他人保留自主意愿，关系中的配合必须通过沟通与协商确认。')
add('02 总控架构','总控先维护目标与状态',claim='职能1—2：先确定评价基准，再建立当前事实快照。',left=[pair('1 目标与约束维护','输入用户目标、期限、底线和承诺；输出有版本的约束清单。'),pair('关键检查','区分愿望、可验收目标和已经承诺的事项。')],right=[pair('2 观察与状态判断','汇总来源、时间、主观描述与指标；输出全局快照和未知项。'),pair('关键检查','过期资料、矛盾记录与自动抽取结果不能直接覆盖事实。')],notes='全局快照不是整个人生的完整数字复制。它是服务当前问题的有限信息集合，应显示未覆盖内容。用户不需要一开始提供全部领域数据，缺失值也不能默认填零。')
add('02 总控架构','总控检查影响与资源组合',claim='职能3—4：知道一个行动影响哪里，以及组合能否成立。',left=[pair('3 跨领域影响分析','记录受影响领域、作用方向、前置依赖和效果延迟。'),pair('输出','跨域影响清单、备选情景，以及可能推翻判断的条件。')],right=[pair('4 资源与优先级协调','同一周期内汇总固定责任、唯一行动需求与保留量。'),pair('输出','可行组合、明确冲突，以及缩减、替换或延期方案。')],notes='影响箭头需要标明是已知关系、用户陈述还是机制假设。资源核算要统一单位与周期；即使总小时数不超标，具体日历时段仍可能冲突。精力和情绪宜作为状态与边界处理，不能随意折成资金分值。')
add('02 总控架构','总控编排决策并协调执行',claim='职能5—6：选择需要的工作深度，并把真实选择转成行动。',left=[pair('5 决策编排','定位问题阶段，选择相关D领域与M模块，推进S1—S8。'),pair('输出','当前版本的证据、方案、比较、复核与条件建议。')],right=[pair('6 授权与执行协调','核对已有授权、依赖、责任、资源上限与验收。'),pair('输出','具体任务和真实执行状态；未执行的内容保持未执行。')],notes='简单可逆的事情可以压缩分析；重大或难以撤回的选择需要更完整的证据和复核。在用户已授权范围内继续工作，不重复索要确认。超出范围的行为不能从建议或状态字段中推导出许可。')
add('02 总控架构','总控保留反馈与可追溯记录',claim='职能7—8：修正判断的同时，让修正原因可检查。',left=[pair('7 分层反馈与适应','按结果成熟程度评估，决定继续、调整、暂停或停止。'),pair('输出','新结果、差异解释、下一步与观察窗口。')],right=[pair('8 证据、复核与版本','保存出处、原预测、变更关系与本版本复核记录。'),pair('输出','可追溯历史与失效提示，避免沿用过期结论。')],notes='用户纠正事实后，应保留更正关系而不是抹掉原判断。数据更新不意味着全部研究重做，总控只重核受到影响的部分。判断质量、执行质量和结果好坏分别讨论，避免仅用最终成败解释一切。')
add('02 总控架构','共同资源账先做可行性检查','formula',claim='核算同一周期、同一单位内的同一种资源。',formula='固定责任 ＋ 唯一行动需求 ＋ 保留量 ≤ 可用总量',items=[pair('去重','同一任务只使用一个全局行动ID；其他领域引用其影响。'),pair('区分备选','互斥的方案分别核算，不能同时计入一个计划。'),pair('保留未知','缺少预算或需求时标未知，不能假定为零。')],notes='公式仅用于能够同口径核算的资源，例如某一周的可用小时。它不能证明方案值得做，也不能代替对日历时段、法律或健康限制的具体检查。已经支出的费用、耗用时间和未解除义务不能因项目停止而消失。')
add('02 总控架构','共享价值不意味着重复投入','columns',claim='合成示例：一份作品同时支持学习和求职。',left=[pair('实际行动','用2小时完成一份展示作品；主责领域为D05学习。'),pair('跨域价值','D04职业可以引用作品用于求职或展示能力。')],right=[pair('正确记录','全局行动A001：投入2小时；关联D05与D04。'),pair('需要避免','把同一投入记成学习2小时加求职2小时；把复用当成两次独立成果。')],notes='多领域价值不必强行相加成一个收益数字。这一页只展示资源去重原则，不判断某份作品的市场价值。作品是否能用于求职，需要具体岗位要求或反馈支持。')
add('02 总控架构','跨领域事项需要统一接口','table',claim='一张行动记录连接主责、影响、资源和反馈。',headers=['字段','需要记录的内容'],rows=[['身份与责任','唯一行动ID、主责领域、负责人、相关目标'],['资源与依赖','时间、资金、已有义务、前置任务与协作条件'],['跨域影响','受影响领域、预期作用、证据或假设'],['观察与停止','预期结果、观察窗口、验收和停止条件'],['状态与版本','当前决定版本、选择与授权、实际执行记录']],notes='例如一次家庭照护事项可由D03主责，D01提供身体照护相关信息，D06负责支出影响，D07负责居住与交通安排。各领域提交影响，但不能各自承诺同一份资源或重复执行同一个动作。')
add('03 九个人生领域','九个领域按生活结果划分','table',claim='按当前需要启用；没有数据的领域保留“未了解”。',headers=['领域','主要维护的结果','领域','主要维护的结果'],rows=[['D01 身体','功能、恢复与照护','D02 心理','感受、应对与心理功能'],['D03 关系','家庭、承诺与相互照护','D04 职业','有用交付、工作与价值创造'],['D05 学习','技能、理解与能力迁移','D06 财务','支付能力、资产与保障'],['D07 日常','居住、交通与基础设施','D08 社群','公共参与与生态责任'],['D09 体验','休闲、审美与自由时间','','']],notes='这是为了便于维护生活结果而提出的可调整分类，不是自然科学证明的唯一人生分类。生活结果可以跨领域产生影响，但执行与资源记录仍需统一。下面逐个展开每个领域的观察、行动、协作和边界。')

