add('03 九个人生领域','跨领域冲突由总控处理','columns',claim='合成示例：临时项目与家庭承诺占用同一晚。',left=[pair('各领域先提供事实','D04确认项目期限与可缩减范围；D03确认家庭承诺及调整可能。'),pair('共同资源检查','M06核对具体时段，\nD01/D02提供已知负荷限制。')],right=[pair('总控生成组合','改交付范围、协商期限、换时段或不接该项目。'),pair('用户作真实取舍','已有承诺是否变更需真实协商；不能由某领域单方面覆盖。')],notes='这个例子不预设工作或家庭永远优先。总控先弄清事实、不可变条件和真实替代方案，再呈现用户要承担的代价。关系中的另一方不是可以被模型随意控制的变量。')
add('04 八阶段决策','八个阶段围绕产物推进','diagram',claim='每一步都有交付物、检查条件和必要的回退路径。',diagram='stages',notes='流程不是强制单向流水线。缺事实返回S2，方案不可行返回S3，目标改变返回S1。后续页把每一步的输入、方法、产物和回退讲清楚。所有阶段都接受目标、证据、伦理与资源检查。',sources=[ENGINE])
stage_specs=[
 ('S1 定义问题','先说清正在决定什么',['输入：当前愿望、期限、资源、底线与已有授权。','方法：区分目标、手段、硬约束和价值偏好。'],['产物：一句话问题、相关领域、目标与约束清单。','回退：缺少会改变选择的目标信息时，先澄清关键问题。'],'逻辑、认识论、决策理论、伦理、心理、系统科学','合成示例：不是泛问“学什么”，而是“在既定时间内，怎样完成一份能验证能力的作品”。'),
 ('S2 建立事实','把证据和猜测分开',['输入：用户陈述、文件、已授权来源与全局快照。','方法：核对原始来源、时间、适用范围和矛盾信息。'],['产物：证据账本、当前输入版本与关键未知。','回退：关键证据不足时限定补证预算，保留条件分析。'],'科学方法、调查研究、统计、历史、英语检索、数据与AI','日历计划只能说明安排，不能自动证明做过。模型抽取的金额、日期和承诺是候选记录，重要字段需要核对。'),
 ('S3 生成方案','把目标转成真实备选',['输入：目标、约束、事实与关键未知。','方法：提出不同路径，包括现状、暂缓、缩减、替代与试行。'],['产物：方案ID、行动内容、进入条件、资源与退出方式。','回退：只有一个方案时检查是否遗漏真实选择。'],'决策理论、系统工程、经济、博弈、制度组织、政治经济学','真实备选需要能够采取且有意义。不能用明显差的方案陪衬预设答案；也不能把行业标签直接当作具体行动。'),
 ('S4 约束与比较','先筛可行，再讨论优劣',['输入：方案需求、整体资源、已承诺事项与偏好。','方法：检查硬约束，再比较收益、成本、风险与可逆性。'],['产物：可行组合、同口径比较与反转条件。','回退：无可行方案则重设方案；不能靠高分抵消底线。'],'数学、统计、决策、运筹、经济、博弈；按需财务法律健康','概率可靠时可用期望效用或决策树；概率不可靠时改用情景、区间与反转条件。任何计算都要保留单位和实际输入。'),
 ('S5 反驳与复核','主动寻找建议可能错在哪里',['输入：当前版本证据、比较和拟推荐方案。','方法：找最强反例，检查计算、替代解释与跨领域损害。'],['产物：复核意见、问题清单及处理状态。','回退：按缺口返回相关阶段，只重做受影响部分。'],'逻辑、科学方法、统计、因果、心理、系统与领域知识','R01检查的是证据和推理，而不是投票背书。多个模型引用同一材料只是一份证据，模型间一致不能替代专业核验。'),
 ('S6 建议与取舍','讲清依据和必须承担的代价',['输入：已比较方案、复核结果与尚存不确定性。','方法：说明成立条件、真实取舍、最大未知与退出方式。'],['产物：条件建议或可供选择方案，独立记录用户选择。','回退：偏好未定时可保留多个方案，不虚构唯一第一。'],'决策、伦理、心理、表达沟通；按需谈判与博弈','建议的证据状态与用户是否愿意选择是两回事。用户愿意尝试，不会自动提高证据质量；用户暂缓后，应尊重其实际状态。'),
 ('S7 授权执行','把真实选择变成可验收行动',['输入：具体方案、实际选择、已有授权与依赖。','方法：安排责任、期限、资源上限、验收与停止条件。'],['产物：唯一行动ID、任务清单及实际执行记录。','回退：条件未具备时保留草案；已授权可逆工作继续。'],'管理、项目管理、运筹、组织、沟通、行为科学与自动化','授权要绑定具体内容，不能用一个“已同意”布尔值概括无限范围。没有操作记录时应写执行情况未知，不能默认已经开始或完成。'),
 ('S8 反馈更新','保留原预测，用新结果修正',['输入：原预期、实际执行、成熟结果与环境变化。','方法：区分测量、执行、机制假设、环境与偶然因素。'],['产物：差异解释、新版本、继续或调整的下一步。','回退：实质变化返回最早受影响阶段，保留历史记录。'],'统计、因果与实验、控制方法、调查实践、数据与管理复盘','前后变化不能直接证明因果。没有实际执行，或观察窗口尚未覆盖效果延迟时，先核实与等待；不要把沉默或缺失记录解释为失败。')]
for title,claim,l,r,k,n in stage_specs:
 add('04 八阶段决策',title,claim=claim,left=[pair('输入与处理',l[0]),pair('采取的方法',l[1])],right=[pair('必要产物',r[0]),pair('检查与回退',r[1])],bottom='调用知识：'+k,notes=n,sources=[ENGINE])
add('04 八阶段决策','比较方法取决于证据条件','table',headers=['当前条件','采用的方法','需要检查'],rows=[['只有明确底线','先做可行性筛选','违反硬约束的方案不进入原条件推荐'],['多个目标、偏好明确','比较支配关系与真实取舍','评分确有必要才使用，解释尺度与权重'],['概率与后果有依据','决策树、期望效用等','同时检查不可承受损失与可逆性'],['概率不可靠','情景、区间与反转条件','情景不完备，不宣称已求得最优'],['行动效果未知','有资源上限的可逆小试验','预先写观察窗口、指标与停止条件']],notes='方法选择本身也是判断。计算越复杂不代表越可信；如果输入是猜测，精确计算只会让猜测显得准确。没有概率依据时，呈现清楚的条件分析往往更合适。',sources=[ENGINE])
add('04 八阶段决策','三个状态必须分别记录','table',claim='形成建议、作出选择与实际执行是三个不同事实。',headers=['状态','允许的值','回答什么问题'],rows=[['建议状态','待补证 / 条件建议 / 建议可供选择','证据支持到什么程度？'],['用户选择','未知 / 未决定 / 已决定 / 暂缓','用户实际上作了什么选择？'],['执行状态','未知 / 未开始 / 执行中 / 已暂停 / 已完成 / 已停止','行动实际上进行到哪里？']],notes='用户已经决定不能消除证据缺口，建议已被查看不能证明用户接受，用户接受也不能证明行动完成。三个字段都需要自己的来源与时间。记录的状态只是描述，不会自动创造工具授权。',sources=[ENGINE])
add('04 八阶段决策','条件变化后，旧结论可能失效','three',claim='同一个方案ID不代表内容和授权始终相同。',items=[pair('发现变化','目标、关键事实、约束、资源或方案内容发生实质改变。'),pair('建立新版本','保留旧记录，更新快照及受影响的证据和约束。'),pair('重新核对','重做相关比较与复核；检查原选择和授权是否仍适用。')],notes='合成示例：原方案只需2小时，修改后变成10小时，即使ID未变，也不能沿用旧的资源结论。内容指纹用于发现变化，但指纹匹配或更新本身不能证明人或模型实际完成了重核。',sources=[ENGINE])
add('04 八阶段决策','补证与复核也要有终点',left=[pair('先问信息是否有用','什么答案会改变可行方案或下一步？取得信息要花多少代价？'),pair('设研究边界','写明预算、截止时间和拿不到资料时的处理方案。')],right=[pair('停止循环的条件','信息不会改变行动，或预算、期限与来源条件已到边界。'),pair('可交付的结果','剩余未知、条件建议，以及可逆的下一步。')],notes='等待也有成本。不能把证据尚不完美变成无限研究的理由，也不能为了结束研究而虚构确定性。停止补证可以与保留未知同时发生。',sources=[ENGINE])
