add('09 贯穿案例','原组合超出时间上限','table',claim='2 ＋ 5 ＋ 4 ＋ 1 ＝ 12小时，超过10小时。',headers=['事项','原组合','组合A','组合B'],rows=[['家庭承诺','2小时','2小时','2小时'],['客户项目','5小时','5小时','3小时'],['能力学习','4小时','2小时','4小时'],['保留缓冲','1小时','1小时','1小时'],['合计','12小时：超2小时','10小时：数量可行','10小时：数量可行']],notes='组合A必须确认学习可缩减到2小时仍有价值；组合B必须确认项目3小时仍能满足交付。总量可行还要检查具体时段，以及是否存在未计入的承诺。这里只计算时间，没有虚构项目收益或成功率。',sources=[ARCH])
add('09 贯穿案例','数量可行的组合仍需补证与取舍',left=[pair('关键补问','项目能否缩减到3小时？若不能，组合B不成立。'),pair('模块工作','D04核实交付范围；D05提出最小练习；M06检查日历。')],right=[pair('条件建议','若项目不能缩减而学习能缩减，可讨论组合A及其代价。'),pair('复核与选择','R01查遗漏和重复记账；分别记录用户选择、授权范围与实际执行。')],notes='不应因为项目看起来更能赚钱就自动删掉家庭或缓冲。还可以提出延期、替代或不启动的方案。最后推荐状态取决于已经核实什么；用户是否愿意接受学习缩减是另一条独立信息。',sources=[ARCH,ENGINE])
add('09 贯穿案例','反馈先核实发生了什么',claim='合成后续：有课程计划，但没有作品记录。',left=[pair('先查事实缺口','先问是否已经练习或完成作品，只是未被当前来源记录。'),pair('如果确实尚未完成','核实实际观看、练习与阻碍；目标有效时再比较调整计划。')],right=[pair('如果作品在别处','补充来源，撤回无产出的判断，评估是否改善采集。'),pair('如果目标已暂缓','更新目标与建议状态；不继续用旧目标催促。')],notes='没有文件不等于没有学习，日历安排也不等于实际观看。这个例子同时体现主动补问、证据更正、目标版本和提醒去重。系统不应从局部行为推断“不自律”等人格结论。',sources=[PRO])
